using UnityEngine;

public abstract class ActorController : MonoBehaviour
{
    public int actorId;
    public string actorName;
    public Color actorColor = Color.white;
    public WordProgress wordProgress = new WordProgress();
    public int completedWords = 0;
    public bool isEliminated = false;
    
    protected GameManager gameManager;
    protected Rigidbody rb;
    protected float moveSpeed;
    protected FloatingWordDisplay floatingWordDisplay;
    protected CharacterAnimationController animationController;
    
    protected virtual void Start()
    {
        rb = GetComponent<Rigidbody>();
        gameManager = GameManager.Instance;
        animationController = GetComponent<CharacterAnimationController>();
        
        // Set actor color
        MeshRenderer renderer = GetComponentInChildren<MeshRenderer>();
        if (renderer != null)
        {
            renderer.material.color = actorColor;
        }
        
        // Create floating word display
        CreateFloatingWordDisplay();
    }
    
    public virtual void Initialize(int id, string name, Color color, float speed)
    {
        actorId = id;
        actorName = name;
        //actorColor = color;
        moveSpeed = speed;
        
        MeshRenderer renderer = GetComponentInChildren<MeshRenderer>();
        if (renderer != null)
        {
            renderer.material.color = actorColor;
        }
    }
    
    protected virtual void CreateFloatingWordDisplay()
    {
        GameObject floatingTextObj = new GameObject("FloatingWordDisplay");
        floatingTextObj.transform.SetParent(transform);
        floatingTextObj.transform.localPosition = Vector3.zero;
        
        floatingWordDisplay = floatingTextObj.AddComponent<FloatingWordDisplay>();
    }
    
    public void AssignWord(string word)
    {
        wordProgress.SetWord(word);
        
        if (floatingWordDisplay != null)
        {
            floatingWordDisplay.UpdateWord(wordProgress);
        }
        
        OnWordAssigned(word);
    }
    
    protected virtual void OnWordAssigned(string word)
    {
        // Override in derived classes
    }
    
    public void OnNodeTouched(LetterNode node)
    {
        if (isEliminated || gameManager == null || !gameManager.IsGameActive())
        {
            return;
        }
        
        if (!node.CanTouch(actorId))
        {
            return;
        }
        
        node.SetTouchCooldown(actorId, gameManager.config.touchCooldown);
        node.SetLastTouchedColor(actorColor);
        
        bool isNeeded = wordProgress.IsLetterNeeded(node.letter);
        
        if (isNeeded)
        {
            OnCorrectTouch(node);
        }
        else
        {
            OnWrongTouch(node);
        }
    }
    
    protected virtual void OnCorrectTouch(LetterNode node)
    {
        wordProgress.FillLetter(node.letter);
        
        if (floatingWordDisplay != null)
        {
            floatingWordDisplay.UpdateWord(wordProgress);
        }
        
        // Play correct letter sound only for player
        if (AudioManager.Instance != null && this is PlayerController)
        {
            AudioManager.Instance.PlayCorrectLetter();
        }
        
        if (wordProgress.IsComplete())
        {
            OnWordCompleted();
        }
    }
    
    protected virtual void OnWrongTouch(LetterNode node)
    {
        // Override in derived classes
    }
    
    protected virtual void OnWordCompleted()
    {
        completedWords++;
        
        // Play word complete sound only for player
        if (AudioManager.Instance != null && this is PlayerController)
        {
            AudioManager.Instance.PlayWordComplete();
        }
        
        if (completedWords >= gameManager.config.wordsToWin)
        {
            gameManager.OnActorWon(this);
        }
        else
        {
            gameManager.AssignNewWord(this);
        }
    }
    
    protected void Move(Vector3 direction)
    {
        if (rb != null)
        {
            if (direction.magnitude > 0.1f)
            {
                Vector3 movement = direction.normalized * moveSpeed * Time.fixedDeltaTime;
                rb.MovePosition(rb.position + movement);
                
                // Rotate to face movement direction
                if (movement.magnitude > 0.01f)
                {
                    Quaternion targetRotation = Quaternion.LookRotation(movement);
                    rb.rotation = Quaternion.Slerp(rb.rotation, targetRotation, Time.fixedDeltaTime * 10f);
                }
            }
            else
            {
                // Stop the rigidbody when there's no input to prevent sliding
                rb.linearVelocity = Vector3.zero;
                rb.angularVelocity = Vector3.zero;
            }
        }
    }
}

using MoreMountains.NiceVibrations;
using UnityEngine;

public class PlayerController : ActorController
{
    public float currentHP;
    public float currentTime;
    public ParticleSystem collectLetterFX;
    public ParticleSystem collectWordFX;
    
    private Vector3 moveInput;
    
    protected override void Start()
    {
        base.Start();
        currentHP = gameManager.config.playerStartingHP;
        //currentTime = gameManager.config.playerStartingTime;
    }
    
    protected override void CreateFloatingWordDisplay()
    {
        base.CreateFloatingWordDisplay();
        
        if (floatingWordDisplay != null && gameManager != null)
        {
            floatingWordDisplay.Initialize(
                transform,
                wordProgress,
                gameManager.config.floatingTextHeight,
                gameManager.config.playerFloatingTextSize,
                gameManager.config.unfilledLetterColor,
                gameManager.config.playerFilledLetterColor
            );
        }
    }
    
    void Update()
    {
        
        rb.linearVelocity = Vector3.zero;
        
        if (isEliminated || !gameManager.IsGameActive())
        {
            return;
        }
        
        // Update timer
        currentTime -= Time.deltaTime;
        if (currentTime <= 0)
        {
            currentTime = 0;
            gameManager.OnPlayerLost("Time ran out!");
        }
    }
    
    void FixedUpdate()
    {
        if (isEliminated || !gameManager.IsGameActive())
        {
            return;
        }
        
        // Rotate character model if moving
        if (animationController != null && moveInput.magnitude > 0.01f)
        {
            animationController.RotateTowards(moveInput);
        }
        
        Move(moveInput);
    }
    
    public void SetMoveInput(Vector2 input)
    {
        moveInput = new Vector3(input.x, 0, input.y);
        
        // Set animation based on input
        if (animationController != null)
        {
            if (input.magnitude > 0.1f)
            {
                animationController.SetWalk();
                animationController.RotateTowards(moveInput);
            }
            else
            {
                animationController.SetIdle();
            }
        }
    }

    protected override void OnWordCompleted()
    {
        base.OnWordCompleted();
        collectWordFX.Play(true);
        MMVibrationManager.Vibrate();
        // Trigger strong vibration for word completion
        if (VibrationManager.Instance != null)
        {
            VibrationManager.Instance.VibrateWordComplete();
        }
    }

    protected override void OnCorrectTouch(LetterNode node)
    {
        base.OnCorrectTouch(node);
        collectLetterFX.Play(true);
        MMVibrationManager.Vibrate();
        // Trigger light vibration for correct letter
        if (VibrationManager.Instance != null)
        {
            VibrationManager.Instance.VibrateCorrectLetter();
        }
    }

    protected override void OnWrongTouch(LetterNode node)
    {
        base.OnWrongTouch(node);
        
        // Trigger camera shake effect
        if (CameraShake.Instance != null)
        {
            CameraShake.Instance.Shake();
        }
        MMVibrationManager.Vibrate();
        // Trigger strong vibration for wrong letter
        if (VibrationManager.Instance != null)
        {
            VibrationManager.Instance.VibrateWrongLetter();
        }
        
        // Play wrong letter sound
        if (AudioManager.Instance != null)
        {
            AudioManager.Instance.PlayWrongLetter();
        }
        
        int progress = wordProgress.GetProgress();
        
        // Always deduct HP
        currentHP -= gameManager.config.hpLossAmount;
        
        // If letters collected > 0, randomly remove one letter
        if (progress > 0)
        {
            wordProgress.RemoveRandomFilledLetter();
            
            // Update floating word display
            if (floatingWordDisplay != null)
            {
                floatingWordDisplay.UpdateWord(wordProgress);
            }
        }
        // If no letters collected, deduct time instead
        else if (progress == 0)
        {
            currentTime -= gameManager.config.timeDeductionAtZeroProgress;
            if (currentTime <= 0)
            {
                currentTime = 0;
                gameManager.OnPlayerLost("Time ran out!");
                return;
            }
        }
        
        // Check if HP reached zero
        if (currentHP <= 0)
        {
            currentHP = 0;
            gameManager.OnPlayerLost("HP reached zero!");
        }
    }
}

using UnityEngine;

public class BotController : ActorController
{
    public int mistakeCount = 0;
    
    private LetterNode targetNode;
    private float replanTimer;
    private Vector3 smoothedAvoidanceDirection;
    
    private bool isPaused = false;
    private float pauseTimer = 0f;
    private DifficultySettings difficultySettings;
    
    protected override void Start()
    {
        base.Start();
        replanTimer = Random.Range(0f, gameManager.config.botReplanInterval);
    }
    
    protected override void CreateFloatingWordDisplay()
    {
        base.CreateFloatingWordDisplay();
        
        if (floatingWordDisplay != null && gameManager != null)
        {
            floatingWordDisplay.Initialize(
                transform,
                wordProgress,
                gameManager.config.floatingTextHeight,
                gameManager.config.botFloatingTextSize,
                gameManager.config.botUnfilledLetterColor,
                gameManager.config.botFilledLetterColor
            );
        }
    }
    
    public void SetDifficultySettings(DifficultySettings settings)
    {
        difficultySettings = settings;
    }
    
    void Update()
    {
        rb.linearVelocity = Vector3.zero;
        
        if (isEliminated || !gameManager.IsGameActive())
        {
            return;
        }
        
        // Handle pause timer
        if (isPaused)
        {
            pauseTimer -= Time.deltaTime;
            if (pauseTimer <= 0)
            {
                isPaused = false;
                
                // Resume walking
                if (animationController != null && targetNode != null)
                {
                    animationController.SetWalk();
                }
            }
            return;
        }
        
        replanTimer -= Time.deltaTime;
        if (replanTimer <= 0 || targetNode == null || !IsTargetValid())
        {
            SelectNewTarget();
            replanTimer = gameManager.config.botReplanInterval;
        }
    }
    
    void FixedUpdate()
    {
        if (isEliminated || !gameManager.IsGameActive() || isPaused)
        {
            return;
        }
        
        if (targetNode != null)
        {
            Vector3 direction = (targetNode.transform.position - transform.position);
            direction.y = 0;
            
            // Check for nearby wrong nodes and avoid them
            Vector3 avoidanceDirection = GetAvoidanceDirection();
            
            // Smooth the avoidance direction to prevent jittering
            smoothedAvoidanceDirection = Vector3.Lerp(
                smoothedAvoidanceDirection, 
                avoidanceDirection, 
                Time.fixedDeltaTime * gameManager.config.botAvoidanceSmoothSpeed
            );
            
            if (smoothedAvoidanceDirection.magnitude > 0.1f)
            {
                // Blend target direction with smoothed avoidance direction
                direction = (direction.normalized + smoothedAvoidanceDirection * 1.5f).normalized;
            }
            
            // Rotate character model towards movement direction
            if (animationController != null && direction.magnitude > 0.01f)
            {
                animationController.RotateTowards(direction);
            }
            
            Move(direction.normalized);
        }
        else
        {
            // No target, set idle
            if (animationController != null)
            {
                animationController.SetIdle();
            }
        }
    }
    
    private void SelectNewTarget()
    {
        if (wordProgress.currentWord == null || wordProgress.currentWord.Length == 0)
        {
            if (animationController != null)
            {
                animationController.SetIdle();
            }
            return;
        }
        
        // Find the first unfilled letter
        char targetLetter = '\0';
        for (int i = 0; i < wordProgress.currentWord.Length; i++)
        {
            if (!wordProgress.filledLetters[i])
            {
                targetLetter = wordProgress.currentWord[i];
                break;
            }
        }
        
        if (targetLetter == '\0')
        {
            if (animationController != null)
            {
                animationController.SetIdle();
            }
            return;
        }
        
        // Find the closest node with that letter
        LetterNode[] allNodes = FindObjectsByType<LetterNode>(FindObjectsSortMode.None);
        LetterNode closestNode = null;
        float closestDistance = float.MaxValue;
        
        foreach (LetterNode node in allNodes)
        {
            if (node.letter == targetLetter)
            {
                float distance = Vector3.Distance(transform.position, node.transform.position);
                if (distance < closestDistance)
                {
                    closestDistance = distance;
                    closestNode = node;
                }
            }
        }
        
        targetNode = closestNode;
        
        // Set walk animation when we have a target
        if (targetNode != null && animationController != null)
        {
            animationController.SetWalk();
        }
    }
    
    private bool IsTargetValid()
    {
        if (targetNode == null)
        {
            return false;
        }
        
        return wordProgress.IsLetterNeeded(targetNode.letter);
    }
    
    protected override void OnWrongTouch(LetterNode node)
    {
        base.OnWrongTouch(node);
        
        mistakeCount++;
        
        if (mistakeCount >= gameManager.config.botMistakeLimit)
        {
            isEliminated = true;
            gameObject.SetActive(false);
        }
    }
    
    public bool ShouldAvoidNode(LetterNode node)
    {
        // If avoidance is disabled, don't avoid any nodes
        if (!gameManager.config.botAvoidWrongNodes)
        {
            return false;
        }
        
        // Bot should avoid nodes with letters they don't need
        return !wordProgress.IsLetterNeeded(node.letter);
    }
    
    private Vector3 GetAvoidanceDirection()
    {
        // If avoidance is disabled, return zero
        if (!gameManager.config.botAvoidWrongNodes)
        {
            return Vector3.zero;
        }
        
        Vector3 avoidance = Vector3.zero;
        LetterNode[] allNodes = FindObjectsByType<LetterNode>(FindObjectsSortMode.None);
        float avoidanceRadius = gameManager.config.botAvoidanceRadius;
        int avoidanceCount = 0;
        
        foreach (LetterNode node in allNodes)
        {
            // Check if this is a wrong node
            if (!wordProgress.IsLetterNeeded(node.letter))
            {
                Vector3 toNode = node.transform.position - transform.position;
                toNode.y = 0;
                float distance = toNode.magnitude;
                
                // If we're close to a wrong node, move away from it
                if (distance < avoidanceRadius && distance > 0.1f)
                {
                    // Use squared falloff for smoother transitions
                    float normalizedDistance = distance / avoidanceRadius;
                    float avoidanceStrength = (1f - normalizedDistance) * (1f - normalizedDistance);
                    
                    Vector3 awayFromNode = -toNode.normalized;
                    avoidance += awayFromNode * avoidanceStrength;
                    avoidanceCount++;
                }
            }
        }
        
        // Average the avoidance if multiple nodes are affecting the bot
        if (avoidanceCount > 0)
        {
            avoidance /= avoidanceCount;
        }
        
        // Clamp the magnitude to prevent extreme avoidance
        if (avoidance.magnitude > 1f)
        {
            avoidance = avoidance.normalized;
        }
        
        return avoidance;
    }
    
    protected override void OnCorrectTouch(LetterNode node)
    {
        base.OnCorrectTouch(node);
        
        // Random chance to pause after touching correct letter
        if (difficultySettings != null && Random.value < difficultySettings.botPauseChance)
        {
            isPaused = true;
            pauseTimer = Random.Range(difficultySettings.botPauseMinDuration, difficultySettings.botPauseMaxDuration);
            
            // Set idle animation during pause
            if (animationController != null)
            {
                animationController.SetIdle();
            }
        }
    }
    
    protected override void OnWordAssigned(string word)
    {
        base.OnWordAssigned(word);
        SelectNewTarget();
    }
}

using UnityEngine;
using System.Collections.Generic;
using TMPro;

public class LetterNode : MonoBehaviour
{
    public char letter;
    public TextMeshPro letterText;
    public MeshRenderer nodeRenderer;
    
    private Material nodeMaterial;
    private Color defaultColor = Color.white;
    private Dictionary<int, float> touchCooldowns = new Dictionary<int, float>();
    
    void Start()
    {
        if (nodeRenderer != null)
        {
            nodeMaterial = nodeRenderer.material;
        }
    }
    
    void Update()
    {
        // Update cooldowns
        List<int> keysToRemove = new List<int>();
        List<int> keys = new List<int>(touchCooldowns.Keys);
        
        foreach (int key in keys)
        {
            touchCooldowns[key] = touchCooldowns[key] - Time.deltaTime;
            if (touchCooldowns[key] <= 0)
            {
                keysToRemove.Add(key);
            }
        }
        
        foreach (int key in keysToRemove)
        {
            touchCooldowns.Remove(key);
        }
    }
    
    public void Initialize(char letter)
    {
        this.letter = char.ToUpper(letter);
        if (letterText != null)
        {
            letterText.text = this.letter.ToString();
        }
    }
    
    public bool CanTouch(int actorId)
    {
        return !touchCooldowns.ContainsKey(actorId) || touchCooldowns[actorId] <= 0;
    }
    
    public void SetTouchCooldown(int actorId, float cooldown)
    {
        touchCooldowns[actorId] = cooldown;
    }
    
    public void SetLastTouchedColor(Color color)
    {
        if (nodeMaterial != null)
        {
            nodeMaterial.color = color;
        }
    }
    
    void OnTriggerEnter(Collider other)
    {
        ActorController actor = other.GetComponent<ActorController>();
        if (actor != null)
        {
            // For bots, check if they should avoid this node
            BotController bot = actor as BotController;
            if (bot != null && bot.ShouldAvoidNode(this))
            {
                return; // Don't trigger touch for bots on wrong nodes
            }
            
            actor.OnNodeTouched(this);
        }
    }
}

