using UnityEngine;
using UnityEditor;

public class AssignPrefabsToConfig
{
    public static void Execute()
    {
        GameConfig config = Resources.Load<GameConfig>("GameConfig");
        if (config == null)
        {
            Debug.LogError("GameConfig not found in Resources!");
            return;
        }

        // Assign Bomb Prefab
        GameObject bombPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/BombPrefab.prefab");
        if (bombPrefab != null)
        {
            config.bombPrefab = bombPrefab;
            Debug.Log("Assigned BombPrefab");
        }
        else
        {
            Debug.LogError("BombPrefab not found!");
        }

        // Assign Booster Prefabs
        config.boosterPrefabs = new GameObject[5];
        config.boosterPrefabs[0] = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Booster_Shield.prefab");
        config.boosterPrefabs[1] = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Booster_Slow.prefab");
        config.boosterPrefabs[2] = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Booster_SpeedUp.prefab");
        config.boosterPrefabs[3] = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Booster_Trap.prefab");
        config.boosterPrefabs[4] = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Booster_FreezeAll.prefab");

        for (int i = 0; i < config.boosterPrefabs.Length; i++)
        {
            if (config.boosterPrefabs[i] != null)
            {
                Debug.Log($"Assigned Booster Prefab {i}: {config.boosterPrefabs[i].name}");
            }
            else
            {
                Debug.LogError($"Booster Prefab {i} not found!");
            }
        }

        EditorUtility.SetDirty(config);
        AssetDatabase.SaveAssets();
    }
}

