using UnityEngine;
using UnityEditor;

public class AssignMysteryBoosterToConfig
{
    public static void Execute()
    {
        GameConfig config = Resources.Load<GameConfig>("GameConfig");
        if (config == null)
        {
            Debug.LogError("GameConfig not found in Resources!");
            return;
        }

        GameObject mysteryPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/MysteryBoosterPrefab.prefab");
        if (mysteryPrefab != null)
        {
            config.mysteryBoosterPrefab = mysteryPrefab;
            Debug.Log("Assigned MysteryBoosterPrefab to GameConfig.");
            EditorUtility.SetDirty(config);
            AssetDatabase.SaveAssets();
        }
        else
        {
            Debug.LogError("MysteryBoosterPrefab not found at Assets/Prefabs/MysteryBoosterPrefab.prefab");
        }
    }
}

