using UnityEngine;
using UnityEditor;
using UnityEngine.UI;

public class AssignToastToUIManager
{
    public static void Execute()
    {
        // Find UIManager in the scene
        UIManager uiManager = Object.FindFirstObjectByType<UIManager>();
        if (uiManager == null)
        {
            Debug.LogError("UIManager not found in scene!");
            return;
        }

        // Load ToastUI prefab
        GameObject toastPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/ToastUI.prefab");
        if (toastPrefab == null)
        {
            Debug.LogError("ToastUI prefab not found!");
            return;
        }

        // Instantiate ToastUI under Canvas
        GameObject canvas = GameObject.Find("Canvas");
        if (canvas == null)
        {
            Debug.LogError("Canvas not found!");
            return;
        }

        // Check if ToastPanel already exists to avoid duplicates
        Transform existingToast = canvas.transform.Find("ToastPanel");
        GameObject toastInstance;

        if (existingToast != null)
        {
            toastInstance = existingToast.gameObject;
            Debug.Log("ToastPanel already exists, updating reference.");
        }
        else
        {
            toastInstance = PrefabUtility.InstantiatePrefab(toastPrefab, canvas.transform) as GameObject;
            toastInstance.name = "ToastPanel";
            // Ensure it's at the bottom of the hierarchy to render on top (or set sibling index)
            toastInstance.transform.SetAsLastSibling();
        }

        toastInstance.SetActive(false);

        // Assign to UIManager
        uiManager.toastPanel = toastInstance;
        uiManager.toastText = toastInstance.GetComponentInChildren<Text>();

        EditorUtility.SetDirty(uiManager);
        Debug.Log("Assigned ToastUI to UIManager in " + UnityEngine.SceneManagement.SceneManager.GetActiveScene().name);
    }
}

