using UnityEngine;
using UnityEditor;

public class AssignPowerUpSFX
{
    public static void Execute()
    {
        AudioManager audioManager = Object.FindFirstObjectByType<AudioManager>();
        if (audioManager == null)
        {
            Debug.LogError("AudioManager not found in scene!");
            return;
        }

        AudioClip powerUpClip = AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Sound/power_up_sfx.mp3");
        AudioClip powerDownClip = AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Sound/power_down_sfx.mp3");

        if (powerUpClip != null)
        {
            audioManager.powerUpSFX = powerUpClip;
            Debug.Log("Assigned power_up_sfx.mp3");
        }
        else
        {
            Debug.LogError("power_up_sfx.mp3 not found!");
        }

        if (powerDownClip != null)
        {
            audioManager.powerDownSFX = powerDownClip;
            Debug.Log("Assigned power_down_sfx.mp3");
        }
        else
        {
            Debug.LogError("power_down_sfx.mp3 not found!");
        }

        EditorUtility.SetDirty(audioManager);
    }
}

using UnityEngine;
using UnityEditor;
using UnityEngine.SceneManagement;
using UnityEditor.SceneManagement;

public class FixSceneLocations
{
    public static void Execute()
    {
        // Fix HomeScene
        string wrongHomePath = "Assets/HomeScene.unity";
        string correctHomePath = "Assets/Scenes/HomeScene.unity";

        if (System.IO.File.Exists(wrongHomePath))
        {
            // If the wrong one exists, we assume it has the latest changes (Audio assignment).
            // We want to replace the correct one with this one.

            // First, ensure we aren't locking the file by having it open?
            // EditorSceneManager.NewScene(NewSceneSetup.EmptyScene);

            string error = AssetDatabase.MoveAsset(wrongHomePath, correctHomePath);
            if (string.IsNullOrEmpty(error))
            {
                Debug.Log($"Successfully moved {wrongHomePath} to {correctHomePath}");
            }
            else
            {
                Debug.LogError($"Failed to move HomeScene: {error}");
                // Fallback: Delete target and move?
                // AssetDatabase.DeleteAsset(correctHomePath);
                // AssetDatabase.MoveAsset(wrongHomePath, correctHomePath);
            }
        }
        else
        {
            Debug.Log("Assets/HomeScene.unity not found, nothing to fix.");
        }

        // Check GameplayScene
        string gameplayPath = "Assets/Scenes/GameplayScene.unity";
        Scene gameplayScene = EditorSceneManager.OpenScene(gameplayPath, OpenSceneMode.Single);

        GameObject canvas = GameObject.Find("Canvas");
        if (canvas != null)
        {
            Transform toast = canvas.transform.Find("ToastPanel");
            if (toast != null)
            {
                Debug.Log("ToastPanel found in GameplayScene.");
            }
            else
            {
                Debug.LogError("ToastPanel NOT found in GameplayScene!");
            }
        }
    }
}

